package app.kinnect.live;
import android.Manifest;
import android.app.*;
import android.content.pm.PackageManager;
import android.os.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import org.webrtc.SurfaceViewRenderer;
/** Foreground audio/video calls, interoperable with the web signaling protocol. */
final class NativeCalls implements NativeSocket.Events {
 private final Activity activity;private final NativeSocket socket;private final Handler handler=new Handler(Looper.getMainLooper());
 private Dialog dialog;private LinearLayout root;private TextView status;private SurfaceViewRenderer local,remote;private NativeRtc rtc;
 private String id,requestId,mode;private boolean incoming,ready,accepted,closed;private Runnable permission;
 private android.media.AudioManager audio;private int previousMode;private boolean previousSpeaker;
 NativeCalls(Activity activity,String origin){this.activity=activity;socket=new NativeSocket(origin,this);}
 private TextView text(String value,int size){TextView v=new TextView(activity);v.setText(value);v.setTextColor(0xfff6f0ff);v.setTextSize(size);v.setPadding(16,12,16,12);return v;}
 private Button button(String value,Runnable task){Button b=new Button(activity);b.setText(value);b.setAllCaps(false);b.setOnClickListener(v->task.run());return b;}
 private void toast(String value){Toast.makeText(activity,value,Toast.LENGTH_LONG).show();}
 void start(JSONObject person,String mode){if(!ready){toast("Đang kết nối dịch vụ cuộc gọi. Thử lại sau giây lát.");return;}if(dialog!=null){toast("Bạn đang có cuộc gọi.");return;}this.mode=mode;incoming=false;open(person);permissions(()->media(()->{requestId=java.util.UUID.randomUUID().toString();socket.send(NativeSocket.json("type","call-start","to",person.optString("id"),"mode",mode,"requestId",requestId));status.setText("Đang gọi…");}));}
 private void open(JSONObject person){dialog=new Dialog(activity,android.R.style.Theme_Material_NoActionBar);root=new LinearLayout(activity);root.setOrientation(1);root.setBackgroundColor(0xff141329);root.setPadding(16,24,16,24);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(16,i.getSystemWindowInsetTop()+16,16,i.getSystemWindowInsetBottom()+16);return i;});root.addView(text(person.optString("name"),26));status=text(incoming?"Cuộc gọi đến": "Đang chuẩn bị…",16);root.addView(status);remote=new SurfaceViewRenderer(activity);local=new SurfaceViewRenderer(activity);if(!mode.equals("audio")){root.addView(remote,new LinearLayout.LayoutParams(-1,0,3));root.addView(local,new LinearLayout.LayoutParams(-1,0,1));}else root.addView(text("Cuộc gọi thoại",28),new LinearLayout.LayoutParams(-1,0,1));if(incoming)root.addView(button("Nhận cuộc gọi",()->permissions(()->media(()->{accepted=true;socket.send(NativeSocket.json("type","call-accept","callId",id));status.setText("Đang kết nối…");}))));final boolean[] mic={true},camera={true};root.addView(button("Bật / tắt micro",()->{if(rtc!=null){mic[0]=!mic[0];rtc.microphone(mic[0]);status.setText(mic[0]?"Micro đang bật":"Micro đã tắt");}}));if(!mode.equals("audio")){root.addView(button("Bật / tắt camera",()->{if(rtc!=null){camera[0]=!camera[0];rtc.camera(camera[0]);}}));root.addView(button("Đổi camera",()->{if(rtc!=null)rtc.flip();}));}root.addView(button("Kết thúc",()->end(true)));dialog.setContentView(root);dialog.setOnCancelListener(d->end(true));dialog.show();handler.postDelayed(()->{if(dialog!=null&&!accepted){toast("Cuộc gọi quá thời gian chờ.");end(true);}},50000);}
 private void permissions(Runnable task){boolean camera=mode.equals("audio")||activity.checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED;boolean mic=activity.checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED;if(camera&&mic){task.run();return;}permission=task;activity.requestPermissions(mode.equals("audio")?new String[]{Manifest.permission.RECORD_AUDIO}:new String[]{Manifest.permission.RECORD_AUDIO,Manifest.permission.CAMERA},901);}
 void permissionsResult(int[] grants){Runnable task=permission;permission=null;for(int grant:grants)if(grant!=PackageManager.PERMISSION_GRANTED){toast("Cần cấp quyền để bắt đầu cuộc gọi.");end(true);return;}if(grants.length>0&&task!=null&&dialog!=null)task.run();else end(true);}
 private void media(Runnable done){if(rtc!=null){done.run();return;}final Dialog generation=dialog;NativeApi.shared.call("GET","/api/call-config",null,(config,error,code)->{if(dialog!=generation||closed||dialog==null)return;if(error!=null){toast(error);end(true);return;}try{rtc=new NativeRtc(activity,config,local,remote,new NativeRtc.Events(){public void status(String value){if(status!=null)status.setText(value);}public void signal(String peer,JSONObject payload){try{payload.put("type","call-signal");payload.put("callId",id);socket.send(payload);}catch(JSONException ignored){}}});rtc.media(activity,!mode.equals("audio"));audio=(android.media.AudioManager)activity.getSystemService(Activity.AUDIO_SERVICE);previousMode=audio.getMode();previousSpeaker=audio.isSpeakerphoneOn();audio.setMode(android.media.AudioManager.MODE_IN_COMMUNICATION);audio.setSpeakerphoneOn(!mode.equals("audio"));done.run();}catch(Exception e){toast("Không mở được camera/micro.");end(true);}});}
 public void event(JSONObject m){String type=m.optString("type");if(type.equals("welcome")){ready=true;return;}if(type.equals("call-incoming")){if(dialog!=null){socket.send(NativeSocket.json("type","call-decline","callId",m.optString("callId")));return;}id=m.optString("callId");mode=m.optString("mode","video");incoming=true;accepted=false;open(m.optJSONObject("from"));return;}if(type.equals("call-ringing")){if(dialog!=null&&m.optString("requestId").equals(requestId)){id=m.optString("callId");status.setText("Đang đổ chuông…");}else socket.send(NativeSocket.json("type","call-end","callId",m.optString("callId")));return;}if(type.equals("call-ended")&&dialog!=null&&((id!=null&&id.equals(m.optString("callId")))||(requestId!=null&&requestId.equals(m.optString("requestId"))))){String reason=m.optString("reason");toast(reason.equals("busy")?"Người này đang bận.":reason.equals("unavailable")?"Người này chưa sẵn sàng nhận cuộc gọi.":"Cuộc gọi đã kết thúc.");end(false);return;}if(dialog==null||id==null||!id.equals(m.optString("callId")))return;if(type.equals("call-accepted")&&rtc!=null){accepted=true;status.setText("Đang kết nối…");if(!incoming)rtc.offer("call");handler.postDelayed(()->{if(dialog!=null&&rtc!=null&&status.getText().toString().equals("Đang kết nối…")){toast("Chưa kết nối được media. Vui lòng thử mạng khác.");end(true);}},35000);}if(type.equals("call-signal")&&rtc!=null)rtc.signal("call",m);}
 public void closed(){ready=false;if(dialog!=null){toast("Mất kết nối cuộc gọi.");end(false);}}
 private void end(boolean notify){if(notify&&id!=null)socket.send(NativeSocket.json("type",incoming&&!accepted?"call-decline":"call-end","callId",id));handler.removeCallbacksAndMessages(null);permission=null;Dialog old=dialog;dialog=null;if(old!=null)old.dismiss();if(rtc!=null){rtc.close();rtc=null;}if(audio!=null){audio.setMode(previousMode);audio.setSpeakerphoneOn(previousSpeaker);audio=null;}id=null;requestId=null;accepted=false;}
 void close(){closed=true;end(true);socket.close();}
}
